mapper.select:
SELECT v.external_id AS external_id
FROM channel_user_vaults p
JOIN vaults v ON v.uuid = p.vault_uuid AND v.organization_uuid = p.organization_uuid AND v.workspace_uuid = p.workspace_uuid
WHERE p.organization_uuid = #{identity.OrganizationUUID} AND p.workspace_uuid = #{identity.WorkspaceUUID}
AND p.channel_type = #{identity.ChannelType} AND p.app_id = #{identity.AppID} AND p.actor_id = #{identity.ActorID}
AND (p.identity_uuid IS NULL OR p.identity_uuid = NULLIF(#{identity.IdentityUUID}, '')::uuid)

mapper.update:
UPDATE channel_user_vaults SET identity_uuid = #{identity.IdentityUUID}::uuid
WHERE organization_uuid = #{identity.OrganizationUUID} AND workspace_uuid = #{identity.WorkspaceUUID}
AND channel_type = #{identity.ChannelType} AND app_id = #{identity.AppID} AND actor_id = #{identity.ActorID}
AND identity_uuid IS NULL
